export default function Input({label, name, value, onChange, placeholder, type = "text", required = false, disabled = false, readOnly = false}) {
    const valueProps = onChange ? {value: value ?? "", onChange} : {defaultValue: value ?? ""};
    return <div className="space-y-2">{label && <label className="block text-[13px] font-semibold text-slate-700" htmlFor={name}>{label}</label>}<input id={name} name={name} type={type} {...valueProps} placeholder={placeholder} required={required} disabled={disabled} readOnly={readOnly} className="w-full rounded-xl border border-slate-200 bg-white/70 px-3.5 py-2.5 text-[14px] text-slate-900 outline-none transition placeholder:text-slate-600 hover:border-slate-300 focus:border-blue-500 focus:bg-white focus:ring-4 focus:ring-blue-500/10 disabled:cursor-not-allowed disabled:bg-white disabled:text-slate-600 read-only:cursor-default"/></div>;
}
